+        var parent = NCombatRoom.Instance?.CombatVfxContainer;
+        if (parent == null) return stars;
+
+        foreach (var child in parent.GetChildren())
+        {
+            if (child is Star star)
+            {
+                stars.Add(star);
+            }
+        }
+
+        return stars;
+    }
+}

