 16→/// </summary>
 17→public static class RegentStarRingPatch
 18→{
 19→    // 存储每个玩家的星星控制器
 20→    private static System.Collections.Generic.Dictionary<Player, StarRingController> _playerStarRings = new();
 21→
 22→    /// <summary>
 23→    /// 监听玩家进入战斗，为储君创建星星环绕系统
 24→    /// </summary>
 25→    [HarmonyPatch(typeof(NCombatRoom), nameof(NCombatRoom.CreateAllyNodes))]
 26→    public static class CreateAllyNodesPatch
 27→    {
 28→        public static void Postfix()
 29→        {
 30→            Entry.Logger.Info("[RegentStarRing] CreateAllyNodes called, setting up star rings for Regent players");
 31→
 32→            if (NCombatRoom.Instance == null) return;
 33→
 34→            // 遍历所有玩家
 35→            foreach (var player in CombatManager.Instance.Players)
 36→            {
 37→                // 检查是否是储君角色
 38→                if (player.Character is Regent)
 39→                {
 40→                    SetupStarRingForPlayer(player);
 41→                }
 42→            }
 43→        }
 44→    }
 45→
 46→    /// <summary>
 47→    /// 监听Star数量变化，更新环绕星星
 48→    /// </summary>
 49→    [HarmonyPatch(typeof(PlayerCombatState), nameof(PlayerCombatState.Stars), MethodType.Setter)]
 50→    public static class StarsChangedPatch
 51→    {
 52→        public static void Postfix(PlayerCombatState __instance, int value)
 53→        {
 54→            // 通过CombatManager获取玩家
 55→            var player = GetPlayerFromCombatState(__instance);
 56→            if (player?.Character is not Regent) return;
 57→
 58→            // 延迟一帧更新，确保数值已同步
 59→            if (NCombatRoom.Instance != null)
 60→            {
 61→                NCombatRoom.Instance.CallDeferred(nameof(UpdateStarRingForPlayer), player, value);
 62→            }
 63→        }
 64→
 65→        private static Player? GetPlayerFromCombatState(PlayerCombatState state)
 66→        {
 67→            // 通过遍历所有玩家找到对应的Player
 68→            foreach (var p in CombatManager.Instance.Players)
 69→            {
 70→                if (p.PlayerCombatState == state)
 71→                {
 72→                    return p;
 73→                }
 74→            }
 75→            return null;
 76→        }
 77→    }
 78→
 79→    /// <summary>
 80→    /// 监听战斗结束，清理星星
 81→    /// </summary>
 82→    [HarmonyPatch(typeof(NCombatRoom), nameof(NCombatRoom.OnProceedButtonPressed))]
 83→    public static class CombatEndPatch
 84→    {
 85→        public static void Prefix()
 86→        {
 87→            Entry.Logger.Info("[RegentStarRing] Combat ending, clearing star rings");
 88→            ClearAllStarRings();
 89→        }
 90→    }
 91→
 92→    /// <summary>
 93→    /// 为储君玩家设置星星环绕
 94→    /// </summary>
 95→    private static void SetupStarRingForPlayer(Player player)
 96→    {
 97→        if (NCombatRoom.Instance == null) return;
 98→
 99→        var playerNode = NCombatRoom.Instance.GetCreatureNode(player.Creature);
100→        if (playerNode == null)
101→        {
102→            Entry.Logger.Warn("[RegentStarRing] Could not find player node");
103→            return;
104→        }
105→
106→        // 如果已存在，先移除旧的
107→        if (_playerStarRings.TryGetValue(player, out var existingController))
108→        {
109→            existingController?.QueueFree();
110→            _playerStarRings.Remove(player);
111→        }
112→
113→        // 创建新的星星控制器
114→        var controller = new StarRingController();
115→        playerNode.AddChild(controller);
116→        controller.Initialize(playerNode);
117→
118→        // 设置初始星星数量
119→        int starCount = player.PlayerCombatState?.Stars ?? 0;
120→        controller.SetStarCount(starCount);
121→
122→        _playerStarRings[player] = controller;
123→
124→        Entry.Logger.Info($"[RegentStarRing] Star ring created for Regent player with {starCount} stars");
125→    }
126→
127→    /// <summary>
128→    /// 更新玩家的星星环绕数量
129→    /// </summary>
130→    private static void UpdateStarRingForPlayer(Player player, int starCount)
131→    {
132→        if (_playerStarRings.TryGetValue(player, out var controller) && controller != null)
133→        {
134→            controller.SetStarCount(starCount);
135→            Entry.Logger.Info($"[RegentStarRing] Star count updated to {starCount}");
136→        }
137→        else if (player.Character is Regent)
138→        {
139→            // 如果控制器不存在但玩家是储君，重新创建
140→            SetupStarRingForPlayer(player);
141→        }
142→    }
143→
144→    /// <summary>
145→    /// 清除所有星星环绕
146→    /// </summary>
147→    private static void ClearAllStarRings()
148→    {
149→        foreach (var controller in _playerStarRings.Values)
150→        {
151→            controller?.ClearAllStars(animate: true);
152→            controller?.QueueFree();
153→        }
154→
155→        _playerStarRings.Clear();
156→    }
157→}
