public void SetUpCombat(CombatState state)
{
	if (_state != null)
	{
		throw new InvalidOperationException("Make sure to reset the combat before setting up a new one.");
	}
	_state = state;
	_state.MultiplayerScalingModel?.OnCombatEntered(_state);

