  1→using Godot;
  2→using System.Collections.Generic;
  3→using System.Linq;
  4→using MegaCrit.Sts2.Core.Entities.Players;
  5→using MegaCrit.Sts2.Core.Nodes.Combat;
  6→using MegaCrit.Sts2.Core.Nodes.Rooms;
  7→
  8→namespace RegentFX.Vfx;
  9→
 10→/// <summary>
 11→/// 储君周围环绕星星控制器
 12→/// 管理星星的生成、销毁、旋转动画
 13→/// </summary>
 14→public partial class StarRingController : Node2D
 15→{
 16→    [Export] public float OrbitRadius { get; set; } = 104f;  // 80f * 1.3 = 104f，水平半径提升30%
 17→    [Export] public float OrbitSpeed { get; set; } = 30f;
 18→    [Export] public float StarScaleMin { get; set; } = 0.6f;
 19→    [Export] public float StarScaleMax { get; set; } = 1.0f;
 20→    [Export] public int MaxStarCount { get; set; } = 20;
 21→    [Export] public float SpawnAnimationDuration { get; set; } = 0.3f;
 22→    [Export] public float VerticalOffset { get; set; } = -80f;  // 从-30提升到-80，让星星在角色胸部/头部高度
 23→
 24→    private readonly List<Star> _orbitStars = new();
 25→    private NCreature? _playerNode;
 26→    private float _orbitAngle;
 27→    private bool _isActive;
 28→
 29→    public override void _Ready()
 30→    {
 31→        ZIndex = -1;
 32→    }
 33→
 34→    public override void _Process(double delta)
 35→    {
 36→        if (!_isActive || _playerNode == null) return;
 37→
 38→        // 更新轨道角度
 39→        _orbitAngle += OrbitSpeed * (float)delta;
 40→
 41→        // 更新所有星星位置
 42→        UpdateStarPositions();
 43→    }
 44→
 45→    /// <summary>
 46→    /// 初始化控制器，绑定到玩家节点
 47→    /// </summary>
 48→    public void Initialize(NCreature playerNode)
 49→    {
 50→        _playerNode = playerNode;
 51→        _isActive = true;
 52→
 53→        // 跟随玩家位置
 54→        TopLevel = false;
 55→    }
 56→
 57→    /// <summary>
 58→    /// 设置星星数量
 59→    /// </summary>
 60→    public void SetStarCount(int count)
 61→    {
 62→        int targetCount = Mathf.Min(count, MaxStarCount);
 63→        int currentCount = _orbitStars.Count;
 64→
 65→        if (targetCount > currentCount)
 66→        {
 67→            // 需要增加星星
 68→            for (int i = 0; i < targetCount - currentCount; i++)
 69→            {
 70→                SpawnStarFromBehind();
 71→            }
 72→        }
 73→        else if (targetCount < currentCount)
 74→        {
 75→            // 需要减少星星（直接消失，后续会改为攻击动画）
 76→            for (int i = 0; i < currentCount - targetCount; i++)
 77→            {
 78→                if (_orbitStars.Count > 0)
 79→                {
 80→                    RemoveLastStar();
 81→                }
 82→            }
 83→        }
 84→    }
 85→
 86→    /// <summary>
 87→    /// 从背后生成星星（避免突兀）
 88→    /// </summary>
 89→    private void SpawnStarFromBehind()
 90→    {
 91→        if (_playerNode == null) return;
 92→
 93→        var starScene = GD.Load<PackedScene>("res://RegentFX/scenes/Star.tscn");
 94→        if (starScene == null)
 95→        {
 96→            GD.PushError("[StarRingController] Failed to load Star.tscn");
 97→            return;
 98→        }
 99→
100→        var star = starScene.Instantiate<Star>();
101→        if (star == null) return;
102→
103→        AddChild(star);
104→
105→        // 计算新星星的角度位置（从背后开始，即角度 PI）
106→        float angleOffset = _orbitStars.Count > 0 ? Mathf.Tau / (_orbitStars.Count + 1) : 0f;
107→        float spawnAngle = Mathf.Pi + angleOffset * _orbitStars.Count;
108→
109→        // 初始位置在玩家背后（缩小状态）
110→        Vector2 spawnPos = CalculateOrbitPosition(spawnAngle, 0.3f);
111→        star.Position = spawnPos;
112→        star.Scale = Vector2.Zero;
113→
114→        // 配置星星参数
115→        star.EnablePulse = true;
116→        star.PulseSpeed = 2f + GD.Randf() * 1f;
117→        star.RotationSpeed = 45f + GD.Randf() * 45f;
118→
119→        _orbitStars.Add(star);
120→
121→        // 播放出现动画
122→        AnimateStarSpawn(star, spawnAngle);
123→    }
124→
125→    /// <summary>
126→    /// 播放星星出现动画
127→    /// </summary>
128→    private void AnimateStarSpawn(Star star, float targetAngle)
129→    {
130→        var tween = CreateTween();
131→        tween.SetTrans(Tween.TransitionType.Back);
132→        tween.SetEase(Tween.EaseType.Out);
133→
134→        // 计算目标位置
135→        Vector2 targetPos = CalculateOrbitPosition(targetAngle, 1.0f);
136→
137→        tween.TweenProperty(star, "position", targetPos, SpawnAnimationDuration);
138→        tween.Parallel().TweenProperty(star, "scale", Vector2.One, SpawnAnimationDuration);
139→    }
140→
141→    /// <summary>
142→    /// 移除最后一个星星
143→    /// </summary>
144→    private void RemoveLastStar()
145→    {
146→        if (_orbitStars.Count == 0) return;
147→
148→        var star = _orbitStars[^1];
149→        _orbitStars.RemoveAt(_orbitStars.Count - 1);
150→
151→        // 直接销毁（后续改为攻击动画）
152→        star.QueueFree();
153→    }
154→
155→    /// <summary>
156→    /// 更新所有星星的位置
157→    /// </summary>
158→    private void UpdateStarPositions()
159→    {
160→        if (_orbitStars.Count == 0) return;
161→
162→        float angleStep = Mathf.Tau / _orbitStars.Count;
163→
164→        for (int i = 0; i < _orbitStars.Count; i++)
165→        {
166→            var star = _orbitStars[i];
167→            if (star == null) continue;
168→
169→            // 计算当前角度（基础角度 + 轨道旋转）
170→            float angle = angleStep * i + Mathf.DegToRad(_orbitAngle);
171→
172→            // 计算深度因子（0 = 最前面，1 = 最后面）
173→            float depthFactor = (Mathf.Sin(angle) + 1f) / 2f;
174→
175→            // 根据深度调整缩放（伪3D效果）
176→            float scale = Mathf.Lerp(StarScaleMax, StarScaleMin, depthFactor);
177→            star.Scale = new Vector2(scale, scale);
178→
179→            // 计算位置
180→            star.Position = CalculateOrbitPosition(angle, 1.0f);
181→
182→            // 根据深度调整ZIndex
183→            // 当 sin(angle) > 0 时，星星在轨道前方（应该显示在角色前面）
184→            // 当 sin(angle) < 0 时，星星在轨道后方（应该显示在角色后面）
185→            // 使用较大的ZIndex范围确保层次感
186→            float sinAngle = Mathf.Sin(angle);
187→            if (sinAngle > 0)
188→            {
189→                // 在轨道前方，显示在角色前面（角色ZIndex通常是0或1）
190→                star.ZIndex = 10 + (int)(sinAngle * 10);
191→            }
192→            else
193→            {
194→                // 在轨道后方，显示在角色后面
195→                star.ZIndex = -10 + (int)(sinAngle * 10);
196→            }
197→        }
198→    }
199→
200→    /// <summary>
201→    /// 计算轨道位置
202→    /// </summary>
203→    private Vector2 CalculateOrbitPosition(float angle, float radiusMultiplier)
204→    {
205→        // 椭圆轨道（水平长轴，垂直短轴，产生伪3D效果）
206→        float x = Mathf.Cos(angle) * OrbitRadius * radiusMultiplier;
207→        float y = Mathf.Sin(angle) * OrbitRadius * 0.4f * radiusMultiplier + VerticalOffset;
208→
209→        return new Vector2(x, y);
210→    }
211→
212→    /// <summary>
213→    /// 清除所有星星
214→    /// </summary>
215→    public void ClearAllStars(bool animate = false)
216→    {
217→        if (animate)
218→        {
219→            foreach (var star in _orbitStars)
220→            {
221→                star?.FadeOutAndDestroy(0.3f);
222→            }
223→        }
224→        else
225→        {
226→            foreach (var star in _orbitStars)
227→            {
228→                star?.QueueFree();
229→            }
230→        }
231→
232→        _orbitStars.Clear();
233→    }
234→
235→    /// <summary>
236→    /// 激活/停用控制器
237→    /// </summary>
238→    public void SetActive(bool active)
239→    {
240→        _isActive = active;
241→        Visible = active;
242→    }
243→
244→    public override void _ExitTree()
245→    {
246→        ClearAllStars();
247→        base._ExitTree();
248→    }
249→}
