  8→namespace RegentFX.Vfx;
  9→
 10→/// <summary>
 11→/// 储君周围环绕星星控制器
 12→/// 管理星星的生成、销毁、旋转动画
 13→/// </summary>
 14→public partial class StarRingController : Node2D
 15→{
 16→    [Export] public float OrbitRadius { get; set; } = 104f;  // 80f * 1.3 = 104f，水平半径提升30%
 17→    [Export] public float OrbitSpeed { get; set; } = 30f;
 18→    [Export] public float StarScaleMin { get; set; } = 0.6f;
 19→    [Export] public float StarScaleMax { get; set; } = 1.0f;
 20→    [Export] public int MaxStarCount { get; set; } = 20;
 21→    [Export] public float SpawnAnimationDuration { get; set; } = 0.3f;
 22→    [Export] public float VerticalOffset { get; set; } = -80f;  // 从-30提升到-80，让星星在角色胸部/头部高度
 23→
 24→    private readonly List<Star> _orbitStars = new();
 25→    private NCreature? _playerNode;
 26→    private float _orbitAngle;
 27→    private bool _isActive;
 28→
 29→    public override void _Process(double delta)
 30→    {
 31→        if (!_isActive || _playerNode == null) return;
 32→
 33→        // 更新控制器位置到玩家位置（因为控制器现在在VFX容器中）
 34→        GlobalPosition = _playerNode.GlobalPosition;
 35→
 36→        // 更新轨道角度
 37→        _orbitAngle += OrbitSpeed * (float)delta;
 38→
 39→        // 更新所有星星位置
 40→        UpdateStarPositions();
 41→    }
 42→
 43→    /// <summary>
 44→    /// 初始化控制器，绑定到玩家节点
 45→    /// </summary>
 46→    public void Initialize(NCreature playerNode)
 47→    {
 48→        _playerNode = playerNode;
 49→        _isActive = true;
 50→
 51→        // 初始位置设置为玩家位置
 52→        GlobalPosition = playerNode.GlobalPosition;
 53→    }
 54→
 55→    /// <summary>
 56→    /// 设置星星数量
 57→    /// </summary>
 58→    public void SetStarCount(int count)
 59→    {
 60→        int targetCount = Mathf.Min(count, MaxStarCount);
 61→        int currentCount = _orbitStars.Count;
 62→
 63→        if (targetCount > currentCount)
 64→        {
 65→            // 需要增加星星
 66→            for (int i = 0; i < targetCount - currentCount; i++)
 67→            {
 68→                SpawnStarFromBehind();
 69→            }
 70→        }
 71→        else if (targetCount < currentCount)
 72→        {
 73→            // 需要减少星星（直接消失，后续会改为攻击动画）
 74→            for (int i = 0; i < currentCount - targetCount; i++)
 75→            {
 76→                if (_orbitStars.Count > 0)
 77→                {
 78→                    RemoveLastStar();
 79→                }
 80→            }
 81→        }
 82→    }
 83→
 84→    /// <summary>
 85→    /// 从背后生成星星（避免突兀）
 86→    /// </summary>
 87→    private void SpawnStarFromBehind()
 88→    {
 89→        if (_playerNode == null) return;
 90→
 91→        var starScene = GD.Load<PackedScene>("res://RegentFX/scenes/Star.tscn");
 92→        if (starScene == null)
 93→        {
 94→            GD.PushError("[StarRingController] Failed to load Star.tscn");
 95→            return;
 96→        }
 97→
 98→        var star = starScene.Instantiate<Star>();
 99→        if (star == null) return;
100→
101→        AddChild(star);
102→
103→        // 计算新星星的角度位置（从背后开始，即角度 PI）
104→        float angleOffset = _orbitStars.Count > 0 ? Mathf.Tau / (_orbitStars.Count + 1) : 0f;
105→        float spawnAngle = Mathf.Pi + angleOffset * _orbitStars.Count;
106→
107→        // 初始位置在玩家背后（缩小状态）
108→        Vector2 spawnPos = CalculateOrbitPosition(spawnAngle, 0.3f);
109→        star.Position = spawnPos;
110→        star.Scale = Vector2.Zero;
111→
112→        // 配置星星参数
113→        star.EnablePulse = true;
114→        star.PulseSpeed = 2f + GD.Randf() * 1f;
115→        star.RotationSpeed = 45f + GD.Randf() * 45f;
116→
117→        _orbitStars.Add(star);
118→
119→        // 播放出现动画
120→        AnimateStarSpawn(star, spawnAngle);
121→    }
122→
123→    /// <summary>
124→    /// 播放星星出现动画
125→    /// </summary>
126→    private void AnimateStarSpawn(Star star, float targetAngle)
127→    {
128→        var tween = CreateTween();
129→        tween.SetTrans(Tween.TransitionType.Back);
130→        tween.SetEase(Tween.EaseType.Out);
131→
132→        // 计算目标位置
133→        Vector2 targetPos = CalculateOrbitPosition(targetAngle, 1.0f);
134→
135→        tween.TweenProperty(star, "position", targetPos, SpawnAnimationDuration);
136→        tween.Parallel().TweenProperty(star, "scale", Vector2.One, SpawnAnimationDuration);
137→    }
138→
139→    /// <summary>
140→    /// 移除最后一个星星
141→    /// </summary>
