  7→
  8→namespace RegentFX.Vfx;
  9→
 10→/// <summary>
 11→/// 储君周围环绕星星控制器
 12→/// 管理星星的生成、销毁、旋转动画
 13→/// </summary>
 14→public partial class StarRingController : Node2D
 15→{
 16→    [Export] public float OrbitRadius { get; set; } = 104f;  // 80f * 1.3 = 104f，水平半径提升30%
 17→    [Export] public float OrbitSpeed { get; set; } = 30f;
 18→    [Export] public float StarScaleMin { get; set; } = 0.6f;
 19→    [Export] public float StarScaleMax { get; set; } = 1.0f;
 20→    [Export] public int MaxStarCount { get; set; } = 20;
 21→    [Export] public float SpawnAnimationDuration { get; set; } = 0.3f;
 22→    [Export] public float VerticalOffset { get; set; } = -80f;  // 从-30提升到-80，让星星在角色胸部/头部高度
 23→
 24→    private readonly List<Star> _orbitStars = new();
 25→    private NCreature? _playerNode;
 26→    private float _orbitAngle;
 27→    private bool _isActive;
 28→
 29→    public override void _Process(double delta)
 30→    {
 31→        if (!_isActive || _playerNode == null) return;
 32→
 33→        // 更新控制器位置到玩家位置（因为控制器现在在VFX容器中）
 34→        GlobalPosition = _playerNode.GlobalPosition;
 35→
 36→        // 更新轨道角度
 37→        _orbitAngle += OrbitSpeed * (float)delta;
 38→
 39→        // 更新所有星星位置
 40→        UpdateStarPositions();
 41→    }
 42→
 43→    /// <summary>
 44→    /// 初始化控制器，绑定到玩家节点
 45→    /// </summary>
 46→    public void Initialize(NCreature playerNode)
 47→    {
 48→        _playerNode = playerNode;
 49→        _isActive = true;
 50→
 51→        // 初始位置设置为玩家位置
 52→        GlobalPosition = playerNode.GlobalPosition;
 53→
 54→        // 调试：输出角色ZIndex信息
 55→        var parent = playerNode.GetParent();
 56→        GD.Print($"[StarRing] PlayerNode ZIndex: {playerNode.ZIndex}");
 57→        GD.Print($"[StarRing] PlayerNode Parent: {parent?.Name}");
 58→
 59→        // 设置ZAsRelative为false，使ZIndex为绝对值
 60→        ZAsRelative = false;
 61→    }
 62→
 63→    /// <summary>
 64→    /// 设置星星数量
 65→    /// </summary>
 66→    public void SetStarCount(int count)
 67→    {
 68→        int targetCount = Mathf.Min(count, MaxStarCount);
 69→        int currentCount = _orbitStars.Count;
 70→
 71→        if (targetCount > currentCount)
 72→        {
 73→            // 需要增加星星
 74→            for (int i = 0; i < targetCount - currentCount; i++)
 75→            {
 76→                SpawnStarFromBehind();
 77→            }
 78→        }
 79→        else if (targetCount < currentCount)
 80→        {
 81→            // 需要减少星星（直接消失，后续会改为攻击动画）
 82→            for (int i = 0; i < currentCount - targetCount; i++)
 83→            {
 84→                if (_orbitStars.Count > 0)
 85→                {
 86→                    RemoveLastStar();
 87→                }
 88→            }
 89→        }
 90→    }
 91→
 92→    /// <summary>
 93→    /// 从背后生成星星（避免突兀）
 94→    /// </summary>
 95→    private void SpawnStarFromBehind()
 96→    {
 97→        if (_playerNode == null) return;
 98→
 99→        var starScene = GD.Load<PackedScene>("res://RegentFX/scenes/Star.tscn");
100→        if (starScene == null)
101→        {
102→            GD.PushError("[StarRingController] Failed to load Star.tscn");
103→            return;
104→        }
105→
106→        var star = starScene.Instantiate<Star>();
107→        if (star == null) return;
108→
109→        AddChild(star);
110→
111→        // 计算新星星的角度位置（从背后开始，即角度 PI）
112→        float angleOffset = _orbitStars.Count > 0 ? Mathf.Tau / (_orbitStars.Count + 1) : 0f;
113→        float spawnAngle = Mathf.Pi + angleOffset * _orbitStars.Count;
114→
115→        // 初始位置在玩家背后（缩小状态）
116→        Vector2 spawnPos = CalculateOrbitPosition(spawnAngle, 0.3f);
117→        star.Position = spawnPos;
118→        star.Scale = Vector2.Zero;
119→
120→        // 配置星星参数
121→        star.EnablePulse = true;
122→        star.PulseSpeed = 2f + GD.Randf() * 1f;
123→        star.RotationSpeed = 45f + GD.Randf() * 45f;
124→        star.ZAsRelative = false;  // 使ZIndex为绝对值
125→
126→        _orbitStars.Add(star);
127→
128→        // 播放出现动画
129→        AnimateStarSpawn(star, spawnAngle);
130→    }
131→
132→    /// <summary>
133→    /// 播放星星出现动画
134→    /// </summary>
135→    private void AnimateStarSpawn(Star star, float targetAngle)
136→    {
137→        var tween = CreateTween();
138→        tween.SetTrans(Tween.TransitionType.Back);
139→        tween.SetEase(Tween.EaseType.Out);
140→
141→        // 计算目标位置
142→        Vector2 targetPos = CalculateOrbitPosition(targetAngle, 1.0f);
143→
144→        tween.TweenProperty(star, "position", targetPos, SpawnAnimationDuration);
145→        tween.Parallel().TweenProperty(star, "scale", Vector2.One, SpawnAnimationDuration);
146→    }
147→
148→    /// <summary>
149→    /// 移除最后一个星星
150→    /// </summary>
151→    private void RemoveLastStar()
152→    {
153→        if (_orbitStars.Count == 0) return;
154→
155→        var star = _orbitStars[^1];
156→        _orbitStars.RemoveAt(_orbitStars.Count - 1);
157→
158→        // 直接销毁（后续改为攻击动画）
159→        star.QueueFree();
160→    }
161→
162→    /// <summary>
163→    /// 更新所有星星的位置
164→    /// </summary>
165→    private void UpdateStarPositions()
166→    {
167→        if (_orbitStars.Count == 0) return;
168→
169→        float angleStep = Mathf.Tau / _orbitStars.Count;
170→
171→        for (int i = 0; i < _orbitStars.Count; i++)
172→        {
173→            var star = _orbitStars[i];
174→            if (star == null) continue;
175→
176→            // 计算当前角度（基础角度 + 轨道旋转）
177→            float angle = angleStep * i + Mathf.DegToRad(_orbitAngle);
178→
179→            // 计算深度因子（0 = 最前面，1 = 最后面）
180→            float depthFactor = (Mathf.Sin(angle) + 1f) / 2f;
181→
182→            // 根据深度调整缩放（伪3D效果）
183→            float scale = Mathf.Lerp(StarScaleMax, StarScaleMin, depthFactor);
184→            star.Scale = new Vector2(scale, scale);
185→
186→            // 计算位置
187→            star.Position = CalculateOrbitPosition(angle, 1.0f);
188→
189→            // 根据深度调整ZIndex
190→            // 当 sin(angle) > 0 时，星星在轨道前方（应该显示在角色前面）
191→            // 当 sin(angle) < 0 时，星星在轨道后方（应该显示在角色后面）
192→            // 角色ZIndex = 0
193→            float sinAngle = Mathf.Sin(angle);
194→            if (sinAngle > 0)
195→            {
196→                // 在轨道前方，显示在角色前面
197→                star.ZIndex = 1;
198→            }
199→            else
200→            {
201→                // 在轨道后方，显示在角色后面，使用更低的ZIndex确保被遮挡
202→                star.ZIndex = -10;
203→            }
204→        }
205→    }
206→
207→    /// <summary>
208→    /// 计算轨道位置
209→    /// </summary>
210→    private Vector2 CalculateOrbitPosition(float angle, float radiusMultiplier)
211→    {
212→        // 椭圆轨道（水平长轴，垂直短轴，产生伪3D效果）
213→        float x = Mathf.Cos(angle) * OrbitRadius * radiusMultiplier;
214→        float y = Mathf.Sin(angle) * OrbitRadius * 0.4f * radiusMultiplier + VerticalOffset;
215→
216→        return new Vector2(x, y);
217→    }
218→
219→    /// <summary>
220→    /// 清除所有星星
221→    /// </summary>
222→    public void ClearAllStars(bool animate = false)
223→    {
224→        if (animate)
225→        {
226→            foreach (var star in _orbitStars)
227→            {
228→                star?.FadeOutAndDestroy(0.3f);
229→            }
230→        }
231→        else
232→        {
233→            foreach (var star in _orbitStars)
234→            {
235→                star?.QueueFree();
236→            }
237→        }
238→
239→        _orbitStars.Clear();
240→    }
241→
242→    /// <summary>
243→    /// 激活/停用控制器
244→    /// </summary>
245→    public void SetActive(bool active)
246→    {
247→        _isActive = active;
248→        Visible = active;
249→    }
250→
251→    public override void _ExitTree()
252→    {
253→        ClearAllStars();
254→        base._ExitTree();
255→    }
256→}
