/// <summary>
/// 输出节点层级和ZIndex信息
/// </summary>
private void LogNodeHierarchy(Node node)
{
    Entry.Logger.Info("[StarRing] ========== Node Hierarchy Debug ==========");

    // 输出角色信息
    Entry.Logger.Info($"[StarRing] PlayerNode: {node.Name}, Type: {node.GetType().Name}");
    if (node is CanvasItem nodeCanvas)
    {
        Entry.Logger.Info($"[StarRing] PlayerNode ZIndex: {nodeCanvas.ZIndex}, ZAsRelative: {nodeCanvas.ZAsRelative}");
        Entry.Logger.Info($"[StarRing] PlayerNode Absolute ZIndex: {CalculateAbsoluteZIndex(nodeCanvas)}");
    }

    // 输出角色父节点信息
    var playerParent = node.GetParent();
    Entry.Logger.Info($"[StarRing] PlayerNode Parent: {playerParent?.Name}, Type: {playerParent?.GetType().Name}");
    if (playerParent is CanvasItem playerParentCanvas)
    {
        Entry.Logger.Info($"[StarRing] PlayerNode Parent ZIndex: {playerParentCanvas.ZIndex}, ZAsRelative: {playerParentCanvas.ZAsRelative}");
        Entry.Logger.Info($"[StarRing] PlayerNode Parent Absolute ZIndex: {CalculateAbsoluteZIndex(playerParentCanvas)}");
    }

    // 输出当前控制器信息
    var controllerParent = GetParent();
    Entry.Logger.Info($"[StarRing] StarRingController Parent: {controllerParent?.Name}, Type: {controllerParent?.GetType().Name}");
    if (controllerParent is CanvasItem controllerParentCanvas)
    {
        Entry.Logger.Info($"[StarRing] StarRingController Parent ZIndex: {controllerParentCanvas.ZIndex}, ZAsRelative: {controllerParentCanvas.ZAsRelative}");
        Entry.Logger.Info($"[StarRing] StarRingController Parent Absolute ZIndex: {CalculateAbsoluteZIndex(controllerParentCanvas)}");
    }

    // 查找背景节点
    var bgContainer = FindBgContainer(node);
    if (bgContainer != null)
    {
        Entry.Logger.Info($"[StarRing] BgContainer: {bgContainer.Name}");
        if (bgContainer is CanvasItem bgCanvas)
        {
            Entry.Logger.Info($"[StarRing] BgContainer ZIndex: {bgCanvas.ZIndex}, ZAsRelative: {bgCanvas.ZAsRelative}");
            Entry.Logger.Info($"[StarRing] BgContainer Absolute ZIndex: {CalculateAbsoluteZIndex(bgCanvas)}");
        }
    }

    Entry.Logger.Info("[StarRing] ========== End Debug ==========");
}

/// <summary>
/// 计算绝对ZIndex
/// </summary>
private int CalculateAbsoluteZIndex(CanvasItem item)
{
    int z = item.ZIndex;
    Node? current = item.GetParent();
    while (current != null)
    {
        if (current is CanvasItem canvasItem && canvasItem.ZAsRelative)
        {
            z += canvasItem.ZIndex;
        }
        current = current.GetParent();
    }
    return z;
}

/// <summary>
/// 查找背景容器
/// </summary>
private Node? FindBgContainer(Node startNode)
{
    Node? current = startNode;
    while (current != null)
    {
        if (current.Name.ToString().Contains("Bg", StringComparison.OrdinalIgnoreCase))
        {
            return current;
        }
        // 尝试在当前节点的父节点中查找
        var parent = current.GetParent();
        if (parent != null)
        {
            foreach (Node child in parent.GetChildren())
            {
                if (child.Name.ToString().Contains("Bg", StringComparison.OrdinalIgnoreCase))
                {
                    return child;
                }
            }
        }
        current = parent;
    }
    return null;
}

