    if (node is CanvasItem nodeCanvas)
    {
        Entry.Logger.Info($"[StarRing] PlayerNode ZIndex: {nodeCanvas.ZIndex}, ZAsRelative: {nodeCanvas.ZAsRelative}");
    }

    // 输出角色父节点信息
